import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.max
import kotlin.math.min

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val a = st.nextToken().toLong()
    val b = st.nextToken().toLong()
    val c = st.nextToken().toLong()
    val l = st.nextToken().toLong()

    val base = longArrayOf(a, b, c)
    var ans = 0L

    fun countForMaxIndex(mx: Int): Long {
        val x = base[mx]
        val y = base[(mx + 1) % 3]
        val z = base[(mx + 2) % 3]
        var res = 0L
        val maxDelta = l

        var d = 0L
        while (d <= maxDelta) {
            val X = x + d
            val sumYZ = y + z
            val diffYZ = kotlin.math.abs(y - z)

            // Triangle inequalities:
            // 1) X < y + z  => d < sumYZ - x
            // 2) X > |y - z| => d > diffYZ - x
            // Also d >= 0

            val upper = sumYZ - x - 1 // d <= upper
            if (upper < 0) {
                d++
                continue
            }
            val lower = max(0L, diffYZ - x + 1) // d >= lower

            if (d < lower) {
                d = lower
                if (d > maxDelta) break
            }
            val curUpper = min(upper, maxDelta)
            if (d > curUpper) break

            val remaining = maxDelta - d
            // number of nonnegative integer solutions to dy + dz <= remaining
            val cnt = (remaining + 1) * (remaining + 2) / 2
            res += cnt
            d = curUpper + 1
        }
        return res
    }

    // total ways to distribute l among three sticks (dx, dy, dz >=0, sum<=l)
    val totalWays = (l + 1) * (l + 2) * (l + 3) / 6

    // subtract invalid (degenerate or impossible) where one side >= sum of other two
    var bad = 0L
    for (mx in 0..2) {
        bad += countForMaxIndex(mx)
    }

    ans = totalWays - bad
    println(ans)
}
